parameters.content:
{
  "id": "dda062e5-93dd-4ad8-aa48-4e0bd3e8d590",
  "version": "1.8",
  "name": "ExpenseApproval",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Expense Report Submitted"
      },
      "inputs": {
        "entryPointId": "ca4a91a7-be2f-49de-9f33-cf5eead28055",
        "isDefaultEntryPoint": true
      }
    },
    {
      "id": "logSubmission",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Log Submission Received"
      },
      "inputs": {
        "script": "return {\n  step: \"submission_received\",\n  logged: true,\n  message: \"[STEP 1] Expense report received from \" + ($vars.start.output.submittedBy || \"unknown\") + \". Amount: $\" + ($vars.start.output.amount || 0) + \". Description: \" + ($vars.start.output.description || \"N/A\") + \". Routing to manager for approval.\"\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the node fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "managerApproval",
      "type": "uipath.human-in-the-loop.quick-form",
      "typeVersion": "1.0",
      "display": {
        "label": "Manager Approval"
      },
      "inputs": {
        "title": "Expense Approval Request",
        "priority": "Medium",
        "schema": {
          "schemaId": "a1b2c3d4-e5f6-7890-abcd-111122223333",
          "fields": [
            {
              "id": "submittedby",
              "label": "Submitted By",
              "type": "text",
              "direction": "input",
              "binding": "vars.start.output.submittedBy"
            },
            {
              "id": "description",
              "label": "Expense Description",
              "type": "text",
              "direction": "input",
              "binding": "vars.start.output.description"
            },
            {
              "id": "amount",
              "label": "Amount ($)",
              "type": "number",
              "direction": "input",
              "binding": "vars.start.output.amount"
            },
            {
              "id": "expensedate",
              "label": "Expense Date",
              "type": "text",
              "direction": "input",
              "binding": "vars.start.output.expenseDate"
            },
            {
              "id": "comments",
              "label": "Manager Comments",
              "type": "text",
              "direction": "output",
              "variable": "vars.managerComments"
            }
          ],
          "outcomes": [
            {
              "id": "approve",
              "name": "Approve",
              "type": "string",
              "isPrimary": true,
              "action": "Continue"
            },
            {
              "id": "reject",
              "name": "Reject",
              "type": "string",
              "isPrimary": false,
              "action": "Continue"
            }
          ]
        },
        "recipient": {
          "channels": [
            "Email",
            "ActionCenter"
          ],
          "connections": {},
          "assignee": {
            "type": "group"
          }
        }
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "comments": {
              "type": "string"
            },
            "Action": {
              "type": "string",
              "enum": [
                "Approve",
                "Reject"
              ],
              "default": "Approve"
            }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": [
            "Approve",
            "Reject"
          ],
          "default": "Approve"
        }
      }
    },
    {
      "id": "checkApproval",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Approved?"
      },
      "inputs": {
        "expression": "$vars.managerApproval.status === \"Approve\"",
        "trueLabel": "Approved",
        "falseLabel": "Rejected"
      },
      "outputs": {
        "matchedCase": {
          "type": "string",
          "description": "The label of the matched branch",
          "var": "matchedCase"
        },
        "matchedCaseId": {
          "type": "string",
          "description": "The branch that was taken",
          "var": "matchedCaseId"
        }
      }
    },
    {
      "id": "logApproved",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Log Approval"
